def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    if not nums:
        return 0
    # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    tails = []
    import bisect
    for x in nums:
        # find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
