def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting (tails) with binary search, O(n log n).
    """
    if not nums:
        return 0
    tails = []
    import bisect
    for x in nums:
        # Find insertion point for x in tails (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

