    ops = {'+', '-', '*', '/'}
    for token in tokens:
        if token in ops and len(token) == 1:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # Use integer division without float to avoid overflow issues
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

