def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested, ignoring other characters.
    Handles parentheses '()', square brackets '[]', and curly braces '{}'.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    open_set = set(matching.values())
    stack = []
    for ch in s:
        if ch in open_set:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

