def solve(tokens):
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

