import bisect

def solve(nums):
    # returns length of LIS (strictly increasing)
    tails = []  # tails[i] = min ending value of an increasing subseq of length i+1
    for x in nums:
        # find position to insert x in tails to keep strictly increasing
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

