def solve(a: str, b: str) -> int:
    """Compute the Levenshtein edit distance between strings a and b.
    Operations allowed: insertion, deletion, substitution, each cost 1.
    """
    m, n = len(a), len(b)
    # Ensure the shorter string is b to use less space if needed (optional)
    # We'll build a (m+1) x (n+1) DP table.
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i  # delete all characters from a
    for j in range(n + 1):
        dp[0][j] = j  # insert all characters to a
    for i in range(1, m + 1):
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[m][n]

